#!/usr/bin/env python3
"""Turn a flat firmware binary into a combinational boot ROM (Verilog case).

The FPGA bring-up never relies on memory initialisation or on $readmemh: the
ROM is plain combinational logic indexed by the 16-byte block address, so there
is nothing for the synthesiser to interpret and nothing to get wrong at
power-up.

    python tools/mkrom.py build/fw/b2_hello.bin rtl/board/boot_rom.v
"""
import sys
from pathlib import Path

HEADER = """// ---------------------------------------------------------------------------
// boot_rom.v - GENERATED by tools/mkrom.py.  Do not edit by hand.
//
// Source : {src}
// Size   : {size} bytes ({blocks} x 16-byte blocks)
//
// Combinational 16-byte lookup: idx = word address[15:4].  Out-of-range blocks
// return zero, which the CPU never executes because the image ends earlier.
// ---------------------------------------------------------------------------
`timescale 1ns/1ps
module boot_rom (
    input  wire [11:0]  idx,
    output reg  [127:0] data
);
    always @(*) begin
        case (idx)
"""

FOOTER = """            default: data = 128'd0;
        endcase
    end
endmodule
"""


def main() -> int:
    if len(sys.argv) != 3:
        print(__doc__)
        return 2
    src = Path(sys.argv[1])
    dst = Path(sys.argv[2])
    data = src.read_bytes()
    if not data:
        print("error: %s is empty" % src)
        return 1

    blocks = (len(data) + 15) // 16
    out = [HEADER.format(src=src.as_posix(), size=len(data), blocks=blocks)]
    for i in range(blocks):
        chunk = data[i * 16:(i + 1) * 16].ljust(16, b"\x00")
        word = int.from_bytes(chunk, "little")
        out.append("            12'd%d: data = 128'h%032X;\n" % (i, word))
    out.append(FOOTER)

    dst.parent.mkdir(parents=True, exist_ok=True)
    dst.write_text("".join(out), encoding="utf-8", newline="\n")
    print("mkrom: %s -> %s (%d bytes, %d blocks)" % (src, dst, len(data), blocks))
    return 0


if __name__ == "__main__":
    sys.exit(main())
